class Tokens : CliktCommand(help = "Generate and decode type-prefixed tokens") {
    override fun run() = Unit
}

class Encode : CliktCommand(help = """Generate a token from a numeric ID.

    Requires an ID and either --type (from config) or all of --prefix, --length, --seed.""") {
    val id by argument(help = "Numeric ID to encode").long()
