import com.github.ajalt.clikt.core.PrintHelpMessage
import com.github.ajalt.clikt.core.PrintMessage
import com.github.ajalt.clikt.core.subcommands
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue

class CliTest {

    private val configFile = File.createTempFile("tokens", ".toml").apply {
        deleteOnExit()
        writeText("""
            [u]
            prefix = "U"
            length = 6
            seed = 0x2783DAB

            [inv]
            prefix = "INV"
            length = 8
            seed = 0x3B4FF74
        """.trimIndent())
    }

    private fun cli() = Tokens().subcommands(Encode(), Decode(), ListTypes())

    private fun encode(vararg args: String): String {
        val output = mutableListOf<String>()
        val cmd = cli()
        cmd.currentContext
        // Use parse and capture via context
        val encode = Encode()
        encode.context { console = object : com.github.ajalt.clikt.output.CliktConsole {
            override val lineSeparator: String = "\n"
            override fun print(text: String, error: Boolean) { output.add(text) }
            override fun promptForLine(prompt: String, hideInput: Boolean): String? = null
        }}
        Tokens().subcommands(encode, Decode(), ListTypes()).parse(listOf("encode") + args)
        return output.joinToString("")
    }

    private fun decode(vararg args: String): String {
        val output = mutableListOf<String>()
        val decode = Decode()
        decode.context { console = object : com.github.ajalt.clikt.output.CliktConsole {
            override val lineSeparator: String = "\n"
            override fun print(text: String, error: Boolean) { output.add(text) }
            override fun promptForLine(prompt: String, hideInput: Boolean): String? = null
