import com.github.ajalt.clikt.core.PrintHelpMessage
import com.github.ajalt.clikt.core.PrintMessage
import com.github.ajalt.clikt.core.subcommands
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue

class CliTest {

    private val configFile = File.createTempFile("tokens", ".toml").apply {
        deleteOnExit()
        writeText("""
            [u]
            prefix = "U"
            length = 6
            seed = 0x2783DAB

            [inv]
            prefix = "INV"
            length = 8
            seed = 0x3B4FF74
        """.trimIndent())
    }

    private fun cli() = Tokens().subcommands(Encode(), Decode(), ListTypes())

    private fun encode(vararg args: String): String {
        val output = mutableListOf<String>()
        val cmd = cli()
        cmd.currentContext
        // Use parse and capture via context
        val encode = Encode()
        encode.context { console = object : com.github.ajalt.clikt.output.CliktConsole {
            override val lineSeparator: String = "\n"
            override fun print(text: String, error: Boolean) { output.add(text) }
            override fun promptForLine(prompt: String, hideInput: Boolean): String? = null
        }}
        Tokens().subcommands(encode, Decode(), ListTypes()).parse(listOf("encode") + args)
        return output.joinToString("")
    }

    private fun decode(vararg args: String): String {
        val output = mutableListOf<String>()
        val decode = Decode()
        decode.context { console = object : com.github.ajalt.clikt.output.CliktConsole {
            override val lineSeparator: String = "\n"
            override fun print(text: String, error: Boolean) { output.add(text) }
            override fun promptForLine(prompt: String, hideInput: Boolean): String? = null
        }}
        Tokens().subcommands(Encode(), decode, ListTypes()).parse(listOf("decode") + args)
        return output.joinToString("")
    }

    // --- Encode with --type from config ---

    @Test
    fun `encode with type from config`() {
        val result = encode("--type", "u", "--config", configFile.absolutePath, "42")
        val expected = DynamicToken("U", 6, 0x2783DABL, 42L).value
        assertEquals(expected + "\n", result)
    }

    @Test
    fun `encode invoice type from config`() {
        val result = encode("--type", "inv", "--config", configFile.absolutePath, "1")
        val expected = DynamicToken("INV", 8, 0x3B4FF74L, 1L).value
        assertEquals(expected + "\n", result)
    }

    // --- Encode with explicit params ---

    @Test
    fun `encode with explicit prefix length seed`() {
        val result = encode("--prefix", "U", "--length", "6", "--seed", "0x2783DAB", "42")
        val expected = DynamicToken("U", 6, 0x2783DABL, 42L).value
        assertEquals(expected + "\n", result)
    }

    @Test
    fun `encode explicit params match config type`() {
        val fromType = encode("--type", "u", "--config", configFile.absolutePath, "99")
        val fromExplicit = encode("--prefix", "U", "--length", "6", "--seed", "0x2783DAB", "99")
        assertEquals(fromType, fromExplicit)
    }

    @Test
    fun `encode with decimal seed`() {
        val decimalSeed = 0x2783DABL
        val result = encode("--prefix", "U", "--length", "6", "--seed", decimalSeed.toString(), "42")
        val expected = DynamicToken("U", 6, decimalSeed, 42L).value
        assertEquals(expected + "\n", result)
    }

    // --- Encode roundtrip with decode ---

    @Test
    fun `encode then decode roundtrips`() {
        val encoded = encode("--type", "u", "--config", configFile.absolutePath, "42").trim()
        val decoded = decode("--config", configFile.absolutePath, encoded).trim()
        assertEquals("42", decoded)
    }

    @Test
    fun `encode then decode with explicit params roundtrips`() {
        val encoded = encode("--prefix", "X", "--length", "6", "--seed", "0xABCDEF", "100").trim()
        val decoded = decode("--prefix", "X", "--length", "6", "--seed", "0xABCDEF", encoded).trim()
        assertEquals("100", decoded)
    }

    // --- Decode auto-detects type from prefix ---

    @Test
    fun `decode auto-detects type from prefix`() {
        val token = DynamicToken("U", 6, 0x2783DABL, 7L)
        val decoded = decode("--config", configFile.absolutePath, token.value).trim()
        assertEquals("7", decoded)
    }

    @Test
    fun `decode auto-detects longer prefix`() {
        val token = DynamicToken("INV", 8, 0x3B4FF74L, 123L)
        val decoded = decode("--config", configFile.absolutePath, token.value).trim()
        assertEquals("123", decoded)
    }

    // --- Error cases ---

    @Test
    fun `encode with no args shows help`() {
        assertFailsWith<PrintHelpMessage> {
            cli().parse(listOf("encode"))
        }
    }

    @Test
    fun `encode with type but no id shows help`() {
        assertFailsWith<PrintHelpMessage> {
            cli().parse(listOf("encode", "--type", "u"))
        }
    }

    @Test
    fun `encode with unknown type fails`() {
        assertFailsWith<PrintMessage> {
            cli().parse(listOf("encode", "--type", "nope", "--config", configFile.absolutePath, "1"))
        }
    }

    @Test
    fun `encode with partial explicit params fails`() {
        assertFailsWith<PrintMessage> {
            cli().parse(listOf("encode", "--prefix", "X", "--length", "6", "1"))
        }
    }

    @Test
    fun `decode with unrecognised prefix and no config fails`() {
        val badConfig = File.createTempFile("tokens-empty", ".toml").apply {
            deleteOnExit()
            writeText("")
        }
        assertFailsWith<PrintMessage> {
            cli().parse(listOf("decode", "--config", badConfig.absolutePath, "ZZZ_ABCDEF0"))
        }
    }

    @Test
    fun `encode with negative id fails`() {
        assertFailsWith<PrintMessage> {
            cli().parse(listOf("encode", "--prefix", "U", "--length", "6", "--seed", "0x2783DAB", "--", "-1"))
        }
    }

    @Test
    fun `encode id 0 works`() {
        val result = encode("--prefix", "U", "--length", "6", "--seed", "0x2783DAB", "0")
        val expected = DynamicToken("U", 6, 0x2783DABL, 0L).value
        assertEquals(expected + "\n", result)
    }
}

